from urllib.request import urlopen

def fetch(url):
    try:
        with urlopen(url, timeout=0.5) as r:
            return r.read()
    except TimeoutError:
        return "timed out"

class RetryBudget:
    def __init__(self, max_tokens=10, ratio=0.5):
        self.max, self.ratio, self.tokens = max_tokens, ratio, float(max_tokens)
    def record(self, ok):
        self.tokens = min(self.max, self.tokens + self.ratio) if ok else max(0.0, self.tokens - 1)
    def can_retry(self):
        return self.tokens >= self.max / 2

b, out = RetryBudget(), []
for ok in [False] * 4 + [True] * 2 + [False] * 3:
    b.record(ok)
    out.append(b.can_retry())
