import time

def get_with_retry(fetch, url):
    attempt = 0
    while True:
        try:
            return fetch(url)
        except Exception:
            time.sleep(min(0.5, 0.02 * 2 ** attempt))
            attempt += 1

store, ledger = {}, []

def charge(key, amount):
    if key in store:
        return store[key]
    ledger.append(amount)
    store[key] = (201, f"ch_{len(ledger)}")
    return store[key]

